        <ol class="ideas-method-flow">
          <li data-stage="market">
            <div class="ideas-method-node"><small>1</small><strong>&asymp;650</strong></div>
            <article>
              <span>MARKET SCAN</span>
              <h3>Trend + fundamentals</h3>
              <p>Every usable stock gets a trend score. Fundamentals add business strength or weakness.</p>
            </article>
          </li>
          <li data-stage="directions">
            <div class="ideas-method-node"><small>2</small><strong>&#8599;&#8600;</strong></div>
            <article>
              <span>TWO LEADERBOARDS</span>
              <h3>Long and Short rank separately</h3>
              <div class="ideas-method-direction-pills" aria-label="Separate Long and Short scoring">
                <b class="long">Long rewards strength</b>
                <b class="short">Short rewards weakness</b>
              </div>
              <p>Crowded Shorts lose points. Each direction keeps its own ranking.</p>
            </article>
          </li>
          <li data-stage="review">
            <div class="ideas-method-node"><small>3</small><strong>30+30</strong></div>
            <article>
              <span>DEEP REVIEW</span>
              <h3>News + OpenAI reasoning</h3>
              <p>The best 30 Long and 30 Short candidates get FMP news and an evidence-based OpenAI review.</p>
            </article>
          </li>
          <li data-stage="ideas">
            <div class="ideas-method-node"><small>4</small><strong>5+5</strong></div>
            <article>
              <span>YOUR IDEAS</span>
              <h3>Five Long + five Short</h3>
              <p>The five strongest final scores from each direction appear in their own leaderboard.</p>
            </article>
          </li>
        </ol>
